//! Niri runtime configuration rendering; neutral values, exact generated bytes.
use super::niri_state::Error;
use serde_json::Value;
type Result<T> = std::result::Result<T, Error>;
const OPTIONS: &[&str] = &[
    "animations",
    "blur",
    "shadow",
    "followMouse",
    "naturalScroll",
    "gapsIn",
    "borderSize",
    "rounding",
];
fn invalid(message: &str) -> Error {
    Error {
        kind: "ValueError",
        message: message.into(),
    }
}
fn number(value: &Value, message: &str) -> Result<f64> {
    value
        .as_f64()
        .filter(|v| v.is_finite())
        .ok_or_else(|| invalid(message))
}
fn truthy(value: &Value) -> bool {
    match value {
        Value::Null => false,
        Value::Bool(value) => *value,
        Value::Number(value) => value.as_f64() != Some(0.0),
        Value::String(value) => !value.is_empty(),
        Value::Array(value) => !value.is_empty(),
        Value::Object(value) => !value.is_empty(),
    }
}
fn integer_text(value: &Value) -> Result<String> {
    if value.as_i64().is_some() || value.as_u64().is_some() {
        return text(value);
    }
    let value = number(value, "Invalid output geometry")?.trunc();
    Ok(if value == 0.0 {
        "0".into()
    } else {
        format!("{value:.0}")
    })
}
fn text(value: &Value) -> Result<String> {
    crate::json::encode(value).map_err(|error| invalid(&error.to_string()))
}
pub fn window_job_token(value: &Value) -> Result<String> {
    let value = value
        .as_str()
        .ok_or_else(|| invalid("Invalid opaque window ID"))?;
    Ok(super::niri_state::native_id(value, "window")?.to_string())
}
pub fn valid_window_id(value: &Value) -> bool {
    window_job_token(value).is_ok()
}
pub fn config_path(
    nacre_config: &std::path::Path,
    kind: &str,
    desktop_override: Option<&std::path::Path>,
) -> Result<std::path::PathBuf> {
    if !["palette", "desktop", "monitor", "profile"].contains(&kind) {
        return Err(invalid("Unknown compositor configuration"));
    }
    if kind == "desktop" {
        if let Some(path) = desktop_override {
            return Ok(path.to_owned());
        }
    }
    Ok(nacre_config.join("niri").join(format!("{kind}.kdl")))
}
pub fn keyboard(values: &Value) -> Result<String> {
    let values = values
        .as_object()
        .ok_or_else(|| invalid("Unknown keyboard option"))?;
    if values
        .keys()
        .any(|key| !["layout", "model", "variant", "options", "rules"].contains(&key.as_str()))
    {
        return Err(invalid("Unknown keyboard option"));
    }
    let mut result = String::from("input {\n    keyboard {\n        xkb {\n");
    for (key, value) in values {
        result.push_str(&format!("            {key} {}\n", text(value)?));
    }
    result.push_str("        }\n    }\n}\n");
    Ok(result)
}
pub fn desktop(preferences: &Value) -> Result<String> {
    let preferences = preferences
        .as_object()
        .ok_or_else(|| invalid("Invalid compositor toggle"))?;
    for key in OPTIONS {
        if let Some(value) = preferences.get(*key) {
            if ["gapsIn", "borderSize", "rounding"].contains(key) {
                if !(0.0..=100.0).contains(&number(value, "Invalid compositor dimension")?) {
                    return Err(invalid("Invalid compositor dimension"));
                }
            } else if !value.is_boolean() {
                return Err(invalid("Invalid compositor toggle"));
            }
        }
    }
    let mut lines = Vec::new();
    if let Some(value) = preferences.get("animations") {
        lines.push(format!(
            "animations {{ {} }}",
            if value == true { "" } else { "off;" }
        ));
    }
    let mut layout = Vec::new();
    if let Some(value) = preferences.get("gapsIn") {
        layout.push(format!("gaps {}", text(value)?));
    }
    if let Some(value) = preferences.get("borderSize") {
        layout.push(format!("border {{ width {}; }}", text(value)?));
        layout.push(format!("focus-ring {{ width {}; }}", text(value)?));
    }
    if !layout.is_empty() {
        lines.push(format!("layout {{\n    {}\n}}", layout.join("\n    ")));
    }
    if let Some(value) = preferences.get("rounding") {
        lines.push(format!("window-rule {{\n    exclude app-id=\"^org[.]quickshell$\" title=\"^Nacre Pearl \"\n    geometry-corner-radius {}\n    clip-to-geometry true\n}}",text(value)?));
    }
    let mut rules = Vec::new();
    if let Some(value) = preferences.get("shadow") {
        rules.push(format!(
            "shadow {{ {}; }}",
            if value == true { "on" } else { "off" }
        ));
    }
    if let Some(value) = preferences.get("blur") {
        rules.push(format!("background-effect {{ blur {value}; }}"));
        lines.push(format!("layer-rule {{\n    match namespace=\"^nacre-(topbar|lock-preview|left-menu-handle|right-menu-handle)$\"\n    background-effect {{ blur {value}; }}\n}}"));
    }
    if !rules.is_empty() {
        lines.push(format!("window-rule {{\n    {}\n}}", rules.join("\n    ")));
    }
    let mut input = Vec::new();
    if preferences.get("followMouse") == Some(&Value::Bool(true)) {
        input.push("focus-follows-mouse");
    }
    if let Some(value) = preferences.get("naturalScroll") {
        input.push(if value == true {
            "touchpad { natural-scroll; scroll-factor 0.25; }"
        } else {
            "touchpad { scroll-factor 0.25; }"
        });
    }
    if !input.is_empty() || preferences.contains_key("followMouse") {
        lines.push(format!("input {{\n    {}\n}}", input.join("\n    ")));
    }
    Ok(lines.join("\n") + "\n")
}
pub fn monitors(monitors: &Value) -> Result<String> {
    let monitors = monitors
        .as_array()
        .ok_or_else(|| invalid("Invalid output geometry"))?;
    let mut lines = Vec::new();
    for monitor in monitors {
        let name = monitor
            .get("name")
            .and_then(Value::as_str)
            .filter(|name| !name.is_empty() && !name.chars().any(|c| (c as u32) < 32))
            .ok_or_else(|| invalid("Invalid output name"))?;
        if monitor
            .get("mirrorOf")
            .is_some_and(|v| !v.is_null() && v != "" && v != "none")
        {
            return Err(invalid("Output mirroring is unavailable on niri"));
        }
        if monitor.get("disabled").is_some_and(truthy) {
            return Err(invalid(
                "Disabling outputs is unavailable in this display transaction",
            ));
        }
        for key in [
            "width",
            "height",
            "scale",
            "refreshRate",
            "x",
            "y",
            "transform",
        ] {
            number(
                monitor.get(key).unwrap_or(&Value::from(0)),
                "Invalid output geometry",
            )?;
        }
        let get = |key: &str| -> Result<f64> {
            let value = monitor.get(key).ok_or_else(|| Error {
                kind: "KeyError",
                message: format!("'{key}'"),
            })?;
            number(value, "Invalid output geometry")
        };
        let scale = get("scale")?;
        let width = get("width")?;
        let height = get("height")?;
        let refresh = number(
            monitor.get("refreshRate").unwrap_or(&Value::from(0)),
            "Invalid output geometry",
        )?;
        let transform = number(
            monitor.get("transform").unwrap_or(&Value::from(0)),
            "Invalid output geometry",
        )?;
        if !(0.0 < scale
            && scale <= 10.0
            && 0.0 < width
            && width <= 32768.0
            && 0.0 < height
            && height <= 32768.0
            && (0.0..=1000.0).contains(&refresh)
            && transform.fract() == 0.0
            && (0.0..8.0).contains(&transform))
        {
            return Err(invalid("Invalid output geometry"));
        }
        lines.push(format!("output {} {{", text(&Value::String(name.into()))?));
        if refresh != 0.0 {
            lines.push(format!(
                "    mode \"{}x{}@{refresh:.3}\"",
                width as i64, height as i64
            ));
        }
        lines.push(format!("    scale {}", text(&monitor["scale"])?));
        lines.push(format!(
            "    position x={} y={}",
            integer_text(monitor.get("x").ok_or_else(|| Error {
                kind: "KeyError",
                message: "'x'".into()
            })?)?,
            integer_text(monitor.get("y").ok_or_else(|| Error {
                kind: "KeyError",
                message: "'y'".into()
            })?)?
        ));
        let transforms = [
            "normal",
            "90",
            "180",
            "270",
            "flipped",
            "flipped-90",
            "flipped-180",
            "flipped-270",
        ];
        lines.push(format!(
            "    transform {}",
            text(&Value::from(transforms[transform as usize]))?
        ));
        lines.push("}".into());
    }
    Ok(lines.join("\n") + if lines.is_empty() { "" } else { "\n" })
}
pub fn bindings(source: &str, kind: &str) -> Result<Value> {
    if kind != "bindings" {
        return Err(invalid("Only generated niri bindings can be inspected"));
    }
    if !source.starts_with("// Generated from compositor-contract.json;") {
        return Err(Error {
            kind: "RuntimeError",
            message: "Private KDL overrides require niri's hotkey overlay".into(),
        });
    }
    let pattern = regex::Regex::new(
        r#"^\s+(\S+)\s+(.+?)\s+\{\s+(spawn-sh "(?:[^"\\]|\\.)*"|[a-z-]+);\s+\}$"#,
    )
    .map_err(|error| invalid(&error.to_string()))?;
    let description = regex::Regex::new(r#"hotkey-overlay-title=("(?:[^"\\]|\\.)*")"#)
        .map_err(|error| invalid(&error.to_string()))?;
    let mut records = Vec::new();
    for line in source.lines() {
        let Some(captures) = pattern.captures(line) else {
            continue;
        };
        let keys = captures[1]
            .replace("Super", "SUPER")
            .replace("Ctrl", "CTRL")
            .replace("Alt", "ALT")
            .replace("Shift", "SHIFT");
        let description = description
            .captures(&captures[2])
            .map(|value| crate::json::parse_value(&value[1]))
            .transpose()
            .map_err(|error| Error {
                kind: "JSONDecodeError",
                message: error.to_string(),
            })?
            .unwrap_or(Value::from(""));
        let action = &captures[3];
        let (method, args) = if let Some(command) = action.strip_prefix("spawn-sh ") {
            (
                "exec_cmd",
                vec![crate::json::parse_value(command).map_err(|error| Error {
                    kind: "JSONDecodeError",
                    message: error.to_string(),
                })?],
            )
        } else {
            (action, vec![])
        };
        records.push(serde_json::json!({"keys":keys,"submap":"","flags":{"description":description},"action":{"method":method,"args":args}}));
    }
    Ok(Value::from(records))
}
pub fn binding_query(records: &Value) -> Result<Value> {
    let mut result = Vec::new();
    for record in records
        .as_array()
        .ok_or_else(|| invalid("Malformed binding records"))?
    {
        let keys = record["keys"]
            .as_str()
            .ok_or_else(|| invalid("Malformed binding records"))?
            .split('+')
            .collect::<Vec<_>>();
        let modifiers = keys[..keys.len() - 1]
            .iter()
            .map(|key| match *key {
                "SUPER" => 64,
                "CTRL" => 4,
                "ALT" => 8,
                "SHIFT" => 1,
                _ => 0,
            })
            .sum::<u64>();
        result.push(serde_json::json!({"modmask":modifiers,"key":keys[keys.len()-1],"submap":"","description":record["flags"]["description"],"dispatcher":"__lua","arg":""}));
    }
    Ok(Value::from(result))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn frozen_generated_binding_records_and_query_projection() -> crate::Result<()> {
        let reference: Value = serde_json::from_str(include_str!(
            "../../tests/fixtures/niri-bindings-reference.json"
        ))?;
        for case in reference["cases"].as_array().ok_or("Missing cases")? {
            let input = &case["request"];
            let result = bindings(
                input["text"].as_str().ok_or("Missing source")?,
                input["kind"].as_str().ok_or("Missing kind")?,
            )
            .and_then(|records| {
                if input["method"] == "query" {
                    binding_query(&records)
                } else {
                    Ok(records)
                }
            });
            let (result, exit) = match result {
                Ok(value) => (value, 0),
                Err(error) => (
                    serde_json::json!({"error":error.message,"type":error.kind}),
                    1,
                ),
            };
            assert_eq!(
                crate::json::encode(&result)? + "\n",
                case["observed"]["stdout"],
                "{}",
                input["name"]
            );
            assert_eq!(
                Value::from(exit),
                case["observed"]["exit"],
                "{}",
                input["name"]
            );
        }
        Ok(())
    }
    #[test]
    fn frozen_current_python_rendering_bytes_and_validation() -> crate::Result<()> {
        let reference: Value = serde_json::from_str(include_str!(
            "../../tests/fixtures/niri-config-query-reference.json"
        ))?;
        let mut count = 0;
        for case in reference["cases"].as_array().ok_or("Missing reference")? {
            let input = &case["request"];
            let result = match input["method"].as_str() {
                Some("render_keyboard") => keyboard(&input["args"][0]),
                Some("render_desktop_options") => desktop(&input["args"][0]),
                Some("render_monitors") => monitors(&input["args"][0]),
                _ => continue,
            };
            let (result, exit) = match result {
                Ok(value) => (Value::from(value), 0),
                Err(error) => (
                    serde_json::json!({"error":error.message,"type":error.kind}),
                    1,
                ),
            };
            assert_eq!(
                crate::json::encode(&result)? + "\n",
                case["observed"]["stdout"],
                "{}",
                input["name"]
            );
            assert_eq!(
                Value::from(exit),
                case["observed"]["exit"],
                "{}",
                input["name"]
            );
            count += 1;
        }
        assert_eq!(count, 76);
        Ok(())
    }
    #[test]
    fn frozen_queries_metadata_results_and_bounds() -> crate::Result<()> {
        use super::super::niri_actions::{Backend, Transport};
        struct Fixture {
            snapshot: Value,
            probes: Vec<Value>,
        }
        impl Transport for Fixture {
            fn snapshot(&mut self, timeout: f64, max_bytes: usize) -> Result<Value> {
                self.probes
                    .push(serde_json::json!({"timeout":timeout as i64,"max_bytes":max_bytes}));
                Ok(self.snapshot.clone())
            }
            fn request(
                &mut self,
                _value: Value,
                _timeout: f64,
                _max_bytes: usize,
            ) -> Result<Value> {
                panic!("Pure query must not dispatch an action")
            }
        }
        let states: Value = serde_json::from_str(include_str!(
            "../../tests/fixtures/niri-state-reference.json"
        ))?;
        let snapshot = states["cases"]
            .as_array()
            .ok_or("Missing states")?
            .iter()
            .find(|case| case["request"]["name"] == "initial-u64-output-relative")
            .ok_or("Missing initial state")?["observations"]
            .as_array()
            .ok_or("Missing observations")?
            .last()
            .ok_or("Missing snapshot")?["snapshot"]
            .clone();
        let reference: Value = serde_json::from_str(include_str!(
            "../../tests/fixtures/niri-config-query-reference.json"
        ))?;
        let mut count = 0;
        for case in reference["cases"].as_array().ok_or("Missing cases")? {
            let input = &case["request"];
            let args = &input["args"];
            let kwargs = &input["kwargs"];
            let mut backend = Backend {
                transport: Fixture {
                    snapshot: snapshot.clone(),
                    probes: vec![],
                },
            };
            let result: Result<Value> = match input["method"].as_str() {
                Some("query" | "query_result") => {
                    let name = args[0].as_str().ok_or("Missing query")?;
                    let result = backend.query_bounded(
                        name,
                        kwargs["timeout"].as_f64().unwrap_or(10.0),
                        kwargs["max_bytes"].as_u64().unwrap_or(4 * 1024 * 1024) as usize,
                    );
                    if input["method"] == "query_result" {
                        match result {
                            Ok(value) => Ok(
                                serde_json::json!({"code":0,"stdout":crate::json::encode(&value)?,"stderr":""}),
                            ),
                            Err(error) if kwargs["check"] == false => {
                                Ok(serde_json::json!({"code":1,"stdout":"","stderr":error.message}))
                            }
                            Err(error) => Err(error),
                        }
                    } else {
                        result
                    }
                }
                Some("valid_window_id") => Ok(Value::from(valid_window_id(&args[0]))),
                Some("window_job_token") => window_job_token(&args[0]).map(Value::from),
                Some("config_path") => config_path(
                    &crate::paths::Paths::new(args[0].as_str().ok_or("Missing home")?).config,
                    args[1].as_str().ok_or("Missing kind")?,
                    None,
                )
                .map(|path| Value::from(path.to_string_lossy().as_ref())),
                Some("legacy_power_binding") => Ok(Value::from("")),
                Some("get_desktop_option") => Err(Error {
                    kind: "RuntimeError",
                    message: "Niri does not expose resolved configuration options".into(),
                }),
                _ => continue,
            };
            let (result, exit) = match result {
                Ok(value) => (value, 0),
                Err(error) => (
                    serde_json::json!({"error":error.message,"type":error.kind}),
                    1,
                ),
            };
            assert_eq!(
                crate::json::encode(&result)? + "\n",
                case["observed"]["stdout"],
                "{}",
                input["name"]
            );
            assert_eq!(
                Value::from(exit),
                case["observed"]["exit"],
                "{}",
                input["name"]
            );
            assert_eq!(
                Value::from(backend.transport.probes),
                case["observed"]["probes"],
                "{}",
                input["name"]
            );
            count += 1;
        }
        assert_eq!(count, 34);
        Ok(())
    }
}
